--
-- Struktur des Views `datenm_values_sem_dichte_lehrer_type_3`
--
DROP TABLE IF EXISTS `datenm_values_sem_dichte_lehrer_type_3`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `datenm_values_sem_dichte_lehrer_type_3`  AS SELECT `q`.`id` AS `id`, `q`.`gruppe_id` AS `gruppe_id`, `q`.`teilnehmer_id` AS `teilnehmer_id`, `q`.`fach` AS `fach`, `q`.`datum` AS `datum`, `q`.`thema` AS `thema`, `q`.`bemerkung` AS `bemerkung`, `q`.`wochentag` AS `wochentag`, `q`.`day_number` AS `day_number`, `q`.`lehrkraft_id` AS `lehrkraft_id`, `q`.`id_mtr_rueckkopplung_datenmaske` AS `id_mtr_rueckkopplung_datenmaske`, 3 AS `type`, `q`.`x_kognition` AS `x_kognition`, `q`.`x_sozial` AS `x_sozial`, `q`.`x_affektiv` AS `x_affektiv`, `q`.`x_motivation` AS `x_motivation`, `q`.`x_methodik` AS `x_methodik`, `q`.`x_performanz` AS `x_performanz`, `q`.`x_regulation` AS `x_regulation`, CASE WHEN greatest(abs(`q`.`x_kognition`),abs(`q`.`x_sozial`),abs(`q`.`x_affektiv`),abs(`q`.`x_motivation`),abs(`q`.`x_methodik`),abs(`q`.`x_performanz`),abs(`q`.`x_regulation`)) = abs(`q`.`x_kognition`) THEN 'kognition' WHEN greatest(abs(`q`.`x_kognition`),abs(`q`.`x_sozial`),abs(`q`.`x_affektiv`),abs(`q`.`x_motivation`),abs(`q`.`x_methodik`),abs(`q`.`x_performanz`),abs(`q`.`x_regulation`)) = abs(`q`.`x_sozial`) THEN 'sozial' WHEN greatest(abs(`q`.`x_kognition`),abs(`q`.`x_sozial`),abs(`q`.`x_affektiv`),abs(`q`.`x_motivation`),abs(`q`.`x_methodik`),abs(`q`.`x_performanz`),abs(`q`.`x_regulation`)) = abs(`q`.`x_affektiv`) THEN 'affektiv' WHEN greatest(abs(`q`.`x_kognition`),abs(`q`.`x_sozial`),abs(`q`.`x_affektiv`),abs(`q`.`x_motivation`),abs(`q`.`x_methodik`),abs(`q`.`x_performanz`),abs(`q`.`x_regulation`)) = abs(`q`.`x_motivation`) THEN 'motivation' WHEN greatest(abs(`q`.`x_kognition`),abs(`q`.`x_sozial`),abs(`q`.`x_affektiv`),abs(`q`.`x_motivation`),abs(`q`.`x_methodik`),abs(`q`.`x_performanz`),abs(`q`.`x_regulation`)) = abs(`q`.`x_methodik`) THEN 'methodik' WHEN greatest(abs(`q`.`x_kognition`),abs(`q`.`x_sozial`),abs(`q`.`x_affektiv`),abs(`q`.`x_motivation`),abs(`q`.`x_methodik`),abs(`q`.`x_performanz`),abs(`q`.`x_regulation`)) = abs(`q`.`x_performanz`) THEN 'performanz' ELSE 'regulation' END AS `dominante_dimension`, greatest(abs(`q`.`x_kognition`),abs(`q`.`x_sozial`),abs(`q`.`x_affektiv`),abs(`q`.`x_motivation`),abs(`q`.`x_methodik`),abs(`q`.`x_performanz`),abs(`q`.`x_regulation`)) AS `dominante_dimension_wert`, CASE WHEN `q`.`x_kognition` + `q`.`x_sozial` + `q`.`x_affektiv` + `q`.`x_motivation` + `q`.`x_methodik` + `q`.`x_performanz` + `q`.`x_regulation` > 0 THEN 1 WHEN `q`.`x_kognition` + `q`.`x_sozial` + `q`.`x_affektiv` + `q`.`x_motivation` + `q`.`x_methodik` + `q`.`x_performanz` + `q`.`x_regulation` < 0 THEN -1 ELSE 0 END AS `polaritaet_gesamt`, sqrt(pow(`q`.`x_kognition`,2) + pow(`q`.`x_sozial`,2) + pow(`q`.`x_affektiv`,2) + pow(`q`.`x_motivation`,2) + pow(`q`.`x_methodik`,2) + pow(`q`.`x_performanz`,2) + pow(`q`.`x_regulation`,2)) AS `d_semantisch` FROM (select `d`.`id` AS `id`,`d`.`gruppe_id` AS `gruppe_id`,`d`.`teilnehmer_id` AS `teilnehmer_id`,`d`.`fach` AS `fach`,`d`.`datum` AS `datum`,`d`.`thema` AS `thema`,`d`.`bemerkung` AS `bemerkung`,`d`.`wochentag` AS `wochentag`,`d`.`day_number` AS `day_number`,`d`.`lehrkraft_id` AS `lehrkraft_id`,`d`.`id` AS `id_mtr_rueckkopplung_datenmaske`,coalesce(`t1`.`x_kognition`,0) + coalesce(`t2`.`x_kognition`,0) * (1 - abs(coalesce(`t1`.`x_kognition`,0))) AS `x_kognition`,coalesce(`t1`.`x_sozial`,0) + coalesce(`t2`.`x_sozial`,0) * (1 - abs(coalesce(`t1`.`x_sozial`,0))) AS `x_sozial`,coalesce(`t1`.`x_affektiv`,0) + coalesce(`t2`.`x_affektiv`,0) * (1 - abs(coalesce(`t1`.`x_affektiv`,0))) AS `x_affektiv`,coalesce(`t1`.`x_motivation`,0) + coalesce(`t2`.`x_motivation`,0) * (1 - abs(coalesce(`t1`.`x_motivation`,0))) AS `x_motivation`,coalesce(`t1`.`x_methodik`,0) + coalesce(`t2`.`x_methodik`,0) * (1 - abs(coalesce(`t1`.`x_methodik`,0))) AS `x_methodik`,coalesce(`t1`.`x_performanz`,0) + coalesce(`t2`.`x_performanz`,0) * (1 - abs(coalesce(`t1`.`x_performanz`,0))) AS `x_performanz`,coalesce(`t1`.`x_regulation`,0) + coalesce(`t2`.`x_regulation`,0) * (1 - abs(coalesce(`t1`.`x_regulation`,0))) AS `x_regulation` from ((`mtr_rueckkopplung_datenmaske` `d` left join (select `frzk_semantische_dichte_lehrer_gesamt`.`id_mtr_rueckkopplung_datenmaske` AS `id_mtr_rueckkopplung_datenmaske`,max(`frzk_semantische_dichte_lehrer_gesamt`.`x_kognition`) AS `x_kognition`,max(`frzk_semantische_dichte_lehrer_gesamt`.`x_sozial`) AS `x_sozial`,max(`frzk_semantische_dichte_lehrer_gesamt`.`x_affektiv`) AS `x_affektiv`,max(`frzk_semantische_dichte_lehrer_gesamt`.`x_motivation`) AS `x_motivation`,max(`frzk_semantische_dichte_lehrer_gesamt`.`x_methodik`) AS `x_methodik`,max(`frzk_semantische_dichte_lehrer_gesamt`.`x_performanz`) AS `x_performanz`,max(`frzk_semantische_dichte_lehrer_gesamt`.`x_regulation`) AS `x_regulation` from `frzk_semantische_dichte_lehrer_gesamt` where `frzk_semantische_dichte_lehrer_gesamt`.`type` = 1 group by `frzk_semantische_dichte_lehrer_gesamt`.`id_mtr_rueckkopplung_datenmaske`) `t1` on(`d`.`id` = `t1`.`id_mtr_rueckkopplung_datenmaske`)) left join (select `frzk_semantische_dichte_lehrer_gesamt`.`id_mtr_rueckkopplung_datenmaske` AS `id_mtr_rueckkopplung_datenmaske`,max(`frzk_semantische_dichte_lehrer_gesamt`.`x_kognition`) AS `x_kognition`,max(`frzk_semantische_dichte_lehrer_gesamt`.`x_sozial`) AS `x_sozial`,max(`frzk_semantische_dichte_lehrer_gesamt`.`x_affektiv`) AS `x_affektiv`,max(`frzk_semantische_dichte_lehrer_gesamt`.`x_motivation`) AS `x_motivation`,max(`frzk_semantische_dichte_lehrer_gesamt`.`x_methodik`) AS `x_methodik`,max(`frzk_semantische_dichte_lehrer_gesamt`.`x_performanz`) AS `x_performanz`,max(`frzk_semantische_dichte_lehrer_gesamt`.`x_regulation`) AS `x_regulation` from `frzk_semantische_dichte_lehrer_gesamt` where `frzk_semantische_dichte_lehrer_gesamt`.`type` = 2 group by `frzk_semantische_dichte_lehrer_gesamt`.`id_mtr_rueckkopplung_datenmaske`) `t2` on(`d`.`id` = `t2`.`id_mtr_rueckkopplung_datenmaske`)) where `t1`.`id_mtr_rueckkopplung_datenmaske` is not null or `t2`.`id_mtr_rueckkopplung_datenmaske` is not null) AS `q` ORDER BY `q`.`id` ASC ;

