--
-- Struktur des Views `kohaerenzmatrix_sem_dichte_lehrer_type_1`
--
DROP TABLE IF EXISTS `kohaerenzmatrix_sem_dichte_lehrer_type_1`;

CREATE ALGORITHM=UNDEFINED 
DEFINER=`root`@`localhost` 
SQL SECURITY DEFINER 
VIEW `kohaerenzmatrix_sem_dichte_lehrer_type_1` AS

WITH basis AS (
    SELECT
        id,
        CASE 
            WHEN lehrkraft_id = 1 THEN 'LK_1'
            ELSE 'LK_other'
        END AS gruppe,
        x_kognition,
        x_sozial,
        x_affektiv,
        x_motivation,
        x_methodik,
        x_performanz,
        x_regulation
    FROM sql_semantische_dichte_lehrer_type_1
),

long_data AS (
    SELECT id, gruppe, 'kognition' AS dimension, x_kognition AS wert FROM basis
    UNION ALL
    SELECT id, gruppe, 'sozial' AS dimension, x_sozial AS wert FROM basis
    UNION ALL
    SELECT id, gruppe, 'affektiv' AS dimension, x_affektiv AS wert FROM basis
    UNION ALL
    SELECT id, gruppe, 'motivation' AS dimension, x_motivation AS wert FROM basis
    UNION ALL
    SELECT id, gruppe, 'methodik' AS dimension, x_methodik AS wert FROM basis
    UNION ALL
    SELECT id, gruppe, 'performanz' AS dimension, x_performanz AS wert FROM basis
    UNION ALL
    SELECT id, gruppe, 'regulation' AS dimension, x_regulation AS wert FROM basis
),

paired AS (
    SELECT
        a.gruppe,
        a.dimension AS dimension_1,
        b.dimension AS dimension_2,
        a.wert AS wert_1,
        b.wert AS wert_2
    FROM long_data a
    JOIN long_data b
        ON a.gruppe = b.gruppe
       AND a.id = b.id
)

SELECT
    gruppe,
    dimension_1,
    dimension_2,
    (
        AVG(wert_1 * wert_2)
        - AVG(wert_1) * AVG(wert_2)
    ) / NULLIF(STD(wert_1) * STD(wert_2), 0) AS korrelation

FROM paired

GROUP BY
    gruppe,
    dimension_1,
    dimension_2

ORDER BY
    gruppe,
    FIELD(dimension_1, 'kognition','sozial','affektiv','motivation','methodik','performanz','regulation'),
    FIELD(dimension_2, 'kognition','sozial','affektiv','motivation','methodik','performanz','regulation');

