--
-- Struktur des Views `sql_rueckkopplung_datenmaske_values`
--
DROP TABLE IF EXISTS `sql_rueckkopplung_datenmaske_values`;

CREATE ALGORITHM=UNDEFINED
DEFINER=`root`@`localhost`
SQL SECURITY DEFINER
VIEW `sql_rueckkopplung_datenmaske_values` AS

WITH RECURSIVE numbers AS (
    SELECT 1 AS n
    UNION ALL
    SELECT n + 1
    FROM numbers
    WHERE n < 100
),

split_data AS (
    SELECT
        d.id AS id_mtr_rueckkopplung_datenmaske,
        SUBSTRING_INDEX(SUBSTRING_INDEX(d.bemerkung, '|', numbers.n), '|', -1) AS raw_value
    FROM mtr_rueckkopplung_datenmaske d
    JOIN numbers
        ON numbers.n <= 1 + OCTET_LENGTH(d.bemerkung) - OCTET_LENGTH(REPLACE(d.bemerkung, '|', ''))
    WHERE d.bemerkung IS NOT NULL
      AND OCTET_LENGTH(d.bemerkung) > 50
)

SELECT
    ROW_NUMBER() OVER (ORDER BY split_data.id_mtr_rueckkopplung_datenmaske) AS id,
    split_data.id_mtr_rueckkopplung_datenmaske,
    REPLACE(TRIM(split_data.raw_value), '\'', '') AS value

FROM split_data

WHERE OCTET_LENGTH(split_data.raw_value) > 40

ORDER BY
    split_data.id_mtr_rueckkopplung_datenmaske ASC;
    
-- --------------------------------------------------------

